const aiItems = $input.all();
const results = [];


function parseApplication(item) {
  const json = item.json;
  let data;

  // Already parsed JSON
  if (json.resume && json.cover_letter) {
    return json;
  }

  // Search ALL OpenAI output entries, not just output[0].
  const messages = Array.isArray(json.output)
    ? json.output
    : [];

  for (const message of messages) {
    const content = message.content || [];

    const result = content.find(
      c => c.type === 'output_text' || c.text !== undefined
    );

    if (result) {
      data = result.text;
      break;
    }
  }

  // Other possible n8n output formats
  if (data === undefined) {
    data =
      json.output_text ??
      json.text ??
      json.response ??
      json.result ??
      json;
  }

  // Parse JSON if returned as a string
  if (typeof data === 'string') {
    const clean = data.trim()
      .replace(/^```(?:json)?\s*/i, '')
      .replace(/\s*```$/, '');

    data = JSON.parse(clean);
  }

  // Handle nested structured output
  if (!data?.resume && data?.result?.resume) {
    data = data.result;
  }

  if (!data?.resume && data?.data?.resume) {
    data = data.data;
  }

  // Helpful diagnostic if still unsuccessful
  if (!data?.resume || !data?.cover_letter) {
    throw new Error(
      'Review output is missing documents. ' +
      'Input fields: ' + Object.keys(json).join(', ') +
      ' | Output types: ' +
      messages.map(m => m.type).join(', ') +
      ' | Parsed fields: ' +
      Object.keys(data || {}).join(', ')
    );
  }

  return data;
}


function safeName(value) {
  return String(value || 'Unknown')
    .replace(/[\\/:*?"<>|]/g, '-')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 65);
}

function formatDates(value) {
  const months = [
    'Jan', 'Feb', 'Mar', 'Apr',
    'May', 'Jun', 'Jul', 'Aug',
    'Sep', 'Oct', 'Nov', 'Dec'
  ];

  return String(value || '').replace(
    /\b(\d{4})-(0[1-9]|1[0-2])\b/g,
    (_, year, month) => `${months[Number(month) - 1]} ${year}`
  ).replace(/\s+to\s+/gi, ' – ');
}

function bulletLines(values, limit) {
  return (Array.isArray(values) ? values : [])
    .slice(0, limit)
    .map(value => `• ${value}`)
    .join('\n');
}

for (let i = 0; i < aiItems.length; i++) {
  const data = parseApplication(aiItems[i]);

const jobLink = $('Grab pending Cover Letter Rows')
  .itemMatching(i).json.Link;

if (!jobLink) {
  throw new Error(`Missing job Link for item ${i}`);
}



  const r = data.resume;
  const letter = data.cover_letter;

  // Keep 3 IT positions, limiting their bullets.
  const experienceText = (r.experience || [])
    .filter(job => !/photographer|videographer/i.test(job.title || ''))
    .slice(0, 3)
    .map((job, index) => [
      [job.title, job.employer].filter(Boolean).join(' — '),
   formatDates(job.dates),
      bulletLines(
        job.achievements || job.bullets,
        index === 0 ? 5 : 2
      )
    ].filter(Boolean).join('\n'))
    .join('\n\n');

  // Include at most one technical project.
  const projectText = (r.projects || [])
    .slice(0, 1)
    .map(project => [
      project.name || '',
      bulletLines(project.bullets, 1)
    ].filter(Boolean).join('\n'))
    .join('\n\n');

  const educationText = (r.education || [])
    .map(entry => {
      if (typeof entry === 'string') return entry;
      return [
        entry.degree,
        entry.major,
        entry.school,
        entry.years
      ].filter(Boolean).join(' | ');
    })
    .join('\n');

  // Maximum 10 relevant skills on compact lines.
  const skillsText = (r.skills || [])
    .slice(0, 10)
    .join(' • ');

  // Resume content.
  const resumeText = [
    'ALEX EXAMPLE',
    'Example City, CA | 202-555-0142 | candidate@example.com',
    '',
    r.headline || '',
    '',
    'PROFESSIONAL SUMMARY',
    r.summary || '',
    '',
    'TECHNICAL SKILLS',
    skillsText,
    '',
    'PROFESSIONAL EXPERIENCE',
    experienceText,
    ...(projectText
      ? ['', 'TECHNICAL PROJECT', projectText]
      : []),
    '',
    'EDUCATION',
    educationText
  ].join('\n');

  const company = typeof letter === 'object'
    ? letter.company || 'Company'
    : 'Company';

  const position = typeof letter === 'object'
    ? letter.position || r.headline || 'Position'
    : r.headline || 'Position';

  // Cover letter content.
  const coverText = typeof letter === 'string'
    ? letter
    : [
        'Alex Example',
        'Example City, CA | 202-555-0142 | candidate@example.com',
        '',
        `${company} — ${position}`,
        '',
        letter.salutation || 'Dear Hiring Manager,',
        '',
        letter.body || '',
        '',
        letter.closing || 'Sincerely,',
        letter.signature || 'Alex Example'
      ].join('\n');

  const baseName =
    `Alex Example - ${safeName(company)} - ${safeName(position)}`;


results.push({
  json: {
    document_type: 'resume',
    Link: jobLink,
    file_name: `${baseName} - Resume`,
    content: resumeText,
    company,
    position
  },
  pairedItem: { item: i }
});

results.push({
  json: {
    document_type: 'cover_letter',
    Link: jobLink,
    file_name: `${baseName} - Cover Letter`,
    content: coverText,
    company,
    position
  },
  pairedItem: { item: i }
});

}

return results;

const prepared = $input.all();
const output = [];

function getReviewedData(item) {
  const json = item.json;

  let data = json.output
    ?.flatMap(x => x.content || [])
    .find(x => x.type === 'output_text')?.text ?? json;

  if (typeof data === 'string') {
    data = JSON.parse(
      data.trim()
        .replace(/^```(?:json)?\s*/i, '')
        .replace(/\s*```\s*$/, '')
    );
  }

  if (data.result?.resume) data = data.result;
  if (data.data?.resume) data = data.data;

  if (!data.resume || !data.cover_letter) {
    throw new Error(
      'Reviewed AI output is missing resume or cover_letter'
    );
  }

  return data;
}

// Clean up awkward wording.
function cleanWording(value) {
  let text = String(value ?? '');

  text = text.replace(
    /\bdiagnosed\s+and\s+troubleshot\b/gi,
    'diagnosed and resolved'
  );

  text = text.replace(
    /\btroubleshot\s+and\s+resolved\b/gi,
    'diagnosed and resolved'
  );

  text = text.replace(
    /\btroubleshot\b/gi,
    match => match[0] === match[0].toUpperCase()
      ? 'Diagnosed and resolved'
      : 'diagnosed and resolved'
  );

  return text;
}

function getBullets(job) {
  if (!job) return [];

  const values = job.achievements || job.bullets || [];

  return (Array.isArray(values) ? values : [])
    .map(value => cleanWording(value).trim())
    .filter(Boolean);
}

function formatBullets(values, max) {
  return values
    .slice(0, max)
    .map(value =>
      '• ' + cleanWording(value).replace(/^•\s*/, '')
    )
    .join('\n');
}

function formatSkills(skills) {
  return (Array.isArray(skills) ? skills : [])
    .map(group => {
      const text = cleanWording(group)
        .replace(/^[^:]+:\s*/, '');

      return text
        .split(',')
        .slice(0, 3)
        .map(skill => skill.trim())
        .filter(Boolean)
        .join(', ');
    })
    .filter(Boolean)
    .join(' • ');
}

for (let i = 0; i < prepared.length; i++) {
  const file = prepared[i].json;

  if (!['resume', 'cover_letter'].includes(file.document_type)) {
    throw new Error(
      `Invalid document type for item ${i}: ` +
      `${file.document_type}. Fields: ` +
      Object.keys(file).join(', ')
    );
  }

  const reviewItem = $('Review Application Documents')
    .itemMatching(i);

  const data = getReviewedData(reviewItem);
  const r = data.resume;
  const l = data.cover_letter;

  let replacements;
  let hasProjects = false;

  if (file.document_type === 'resume') {
    const jobs = Array.isArray(r.experience)
      ? r.experience
      : [];

    const findJob = pattern =>
      jobs.find(job =>
        pattern.test(String(job.title || '').trim())
      );

    const sysadmin = findJob(
      /\bsystems?\s+administrators?\b/i
    );

    const specialist = findJob(
      /\bsystems?\s+specialists?\b/i
    );

    const analyst = findJob(
      /\bpc\s+systems?\s+analysts?\b/i
    );

    // Prevent missing work history.
    if (!sysadmin || !specialist || !analyst) {
      throw new Error(
        'Missing required employment history. Titles: ' +
        jobs.map(j => j.title).join(' | ')
      );
    }

    const adminBullets = getBullets(sysadmin);
    const specialistBullets = getBullets(specialist);
    const analystBullets = getBullets(analyst);

    if (
      adminBullets.length < 5 ||
      specialistBullets.length < 2 ||
      analystBullets.length < 2
    ) {
      throw new Error(
        'Insufficient experience bullets. ' +
        `Administrator: ${adminBullets.length}, ` +
        `Specialist: ${specialistBullets.length}, ` +
        `Analyst: ${analystBullets.length}.`
      );
    }

    // Include up to two relevant projects.
    const projects = (
      Array.isArray(r.projects) ? r.projects : []
    )
      .slice(0, 2)
      .map(project => {
        const name = cleanWording(project.name || '');
        const projectBullets = Array.isArray(project.bullets)
          ? project.bullets
          : [];

        return [
          name,
          formatBullets(projectBullets, 1)
        ].filter(Boolean).join('\n');
      })
      .filter(Boolean)
      .join('\n\n');

    hasProjects = Boolean(projects.trim());

    replacements = {
      '{{HEADLINE}}':
        'Systems Administration | Infrastructure Operations | Automation',

      '{{SUMMARY}}':
        cleanWording(r.summary || ''),

      '{{SKILLS}}':
        formatSkills(r.skills),

      // Fuller experience for the two-page layout.
      '{{SYSADMIN_BULLETS}}':
        formatBullets(adminBullets, 7),

      '{{SPECIALIST_BULLETS}}':
        formatBullets(specialistBullets, 3),

      '{{ANALYST_BULLETS}}':
        formatBullets(analystBullets, 3),

      '{{PROJECTS_HEADING}}':
        hasProjects
          ? 'SELECTED TECHNICAL PROJECTS'
          : '',

      '{{PROJECTS}}':
        projects
    };

  } else {
    const company = cleanWording(
      l.company || file.company || ''
    );

    replacements = {
      '{{COMPANY}}': company,

      '{{POSITION}}':
        cleanWording(l.position || file.position || ''),

      '{{SALUTATION}}':
        company
          ? `Hello, ${company} Hiring Team,`
          : 'Hello, Hiring Team,',

      '{{LETTER_BODY}}':
        cleanWording(l.body || ''),

      '{{CLOSING}}':
        cleanWording(l.closing || 'Sincerely,'),

      '{{SIGNATURE}}':
        cleanWording(l.signature || 'Alex Example')
    };
  }

  // Build Google Docs replaceAllText requests.
  const requests = Object.entries(replacements)
    .map(([placeholder, value]) => ({
      replaceAllText: {
        containsText: {
          text: placeholder,
          matchCase: true
        },
        replaceText: String(value)
      }
    }));

  output.push({
    json: {
      ...file,
      hasProjects,
      batchUpdateBody: { requests }
    },
    pairedItem: { item: i }
  });
}

return output;

const copied = $input.all();

return copied.map((item, i) => {
  const original = $('Build Template Replacements')
    .itemMatching(i).json;

  if (!item.json.id) {
    throw new Error('Google Drive returned no file ID');
  }

  return {
    json: {
      ...original,
      doc_id: item.json.id
    },
    pairedItem: { item: i }
  };
});

const responses = $input.all();
const originals = $('Attach Copied File ID').all();

if (responses.length !== originals.length) {
  throw new Error(
    `Item count mismatch: ${responses.length} HTTP responses, ` +
    `${originals.length} copied documents`
  );
}

const jobs = new Map();

for (let i = 0; i < responses.length; i++) {
  const response = responses[i].json;
  const original = originals[i].json;

  const jobLink = original.Link;
  const type = original.document_type;

  // File ID was saved by Attach Copied File ID.
  const fileId = original.doc_id;

  if (!jobLink) {
    throw new Error(`Missing job Link for item ${i}`);
  }

  if (!fileId) {
    throw new Error(`Missing doc_id for item ${i}`);
  }

  if (response.error) {
    throw new Error(
      `Google Docs update failed for item ${i}: ` +
      JSON.stringify(response.error)
    );
  }

  // Confirm the HTTP response refers to the same document.
  if (response.documentId &&
      response.documentId !== fileId) {
    throw new Error(
      `Document ID mismatch for item ${i}`
    );
  }

  const url =
    `https://docs.google.com/document/d/${fileId}/edit`;

  if (!jobs.has(jobLink)) {
    jobs.set(jobLink, {
      Link: jobLink,
      Resume: '',
      'Cover Letter': ''
    });
  }

  const job = jobs.get(jobLink);

  if (type === 'resume') {
    if (job.Resume) {
      throw new Error(`Duplicate resume for ${jobLink}`);
    }
    job.Resume = url;

  } else if (type === 'cover_letter') {
    if (job['Cover Letter']) {
      throw new Error(
        `Duplicate cover letter for ${jobLink}`
      );
    }
    job['Cover Letter'] = url;

  } else {
    throw new Error(
      `Unknown document type: ${type}`
    );
  }
}

// Verify each job has both documents.
for (const job of jobs.values()) {
  if (!job.Resume || !job['Cover Letter']) {
    throw new Error(
      `Missing resume or cover letter for ${job.Link}`
    );
  }
}

return [...jobs.values()].map(job => ({
  json: job
}));

